NetDecorator = NetDecorator or {}
--记录协议发送
local _msgSentMap = {}
--记录时间段
local MSG_COUNT_PERIOD = 60;
--时间段内预警次数间隔
local MSG_COUNT_TIMES_WARN = 30;
--预警间隔
local MSG_INTERVAL_WARN = 0.5;
--协议屏蔽开关（频繁时取消协议发送）
local MSG_SWITCH_CLOSE = true;

function NetDecorator.MonitorMsg(msgName)
    if MSG_SWITCH_CLOSE then
        return
    end
    local serverTime = FuncUtil.GetServerTimeInSec();
    local msgStatisticsTab = _msgSentMap[msgName];
    if msgStatisticsTab then
        --监控发送间隔
        if serverTime - msgStatisticsTab.lastSendTime <= MSG_INTERVAL_WARN then
            log("WARNING:NetDecorator Send Msg too frequently!!!! msg: "..msgName);
        end
        --监控时间段内发送次数
        if serverTime - msgStatisticsTab.recordTime > MSG_COUNT_PERIOD  then
            msgStatisticsTab.count = 1;
            msgStatisticsTab.recordTime = serverTime;
        elseif msgStatisticsTab.count + 1 > MSG_COUNT_TIMES_WARN then
            log("WARNING:NetDecorator Send too many same msg in "..tostring(MSG_COUNT_PERIOD).."seconds!!!! msg: "..msgName);
            msgStatisticsTab.count = 1;
            msgStatisticsTab.recordTime = serverTime;
        else
            msgStatisticsTab.count = msgStatisticsTab.count + 1;
        end
    else
        msgStatisticsTab = {};
        msgStatisticsTab.count = 1;
        msgStatisticsTab.recordTime = serverTime;
        _msgSentMap[msgName] = msgStatisticsTab;
    end
    msgStatisticsTab.lastSendTime = serverTime;
end

local _msgSendTime = {}
function NetDecorator.OnSendMsg(msgName)
    if not msgName then
        return false
    end
    local needBackMsgName = MsgReceive2Send[msgName]
    if not needBackMsgName then
        return false
    end

    local serverTime = FuncUtil.GetServerTimeInSec();
    if _msgSendTime[needBackMsgName] and serverTime - _msgSendTime[needBackMsgName] < 1 then
        --关键包的处理
        --[[for i,v in ipairs(NetUtil.s2cNeedWaiting) do
            if v.callback == needBackMsgName then
                table.remove(NetUtil.s2cNeedWaiting, i);
                if #NetUtil.s2cNeedWaiting == 0 then
                    ConnectionWaitingUI:Hide();
                    NetUtil.c2sTime = 0;
                    log("ClientEntry ----- NetUtil.DispatchPacket  hide  ConnectWaitingUI");
                else
                    -- 更新sendTime
                    NetUtil.c2sTime = NetUtil.s2cNeedWaiting[1].sendTime;
                    log("ClientEntry ----- NetUtil.DispatchPacket change c2sTime:"..NetUtil.c2sTime);
                end
                break;
            end
        end--]]
        log("WARNING:NetDecorator Jump send this time!!!! msg: "..msgName);
        return true
    else
        _msgSendTime[needBackMsgName]=serverTime;
        return false;
    end
end

function NetDecorator.OnReceiveMsg(msgName)
    _msgSendTime[msgName]=nil;
end